// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.27;
import "@openzeppelin/contracts/utils/Base64.sol";
import "@openzeppelin/contracts/utils/Strings.sol";

/// @notice Self-contained fallback metadata; no web host or mutable administrator URI.
library FillOutMetadata {
    function uri(string memory name, string memory label, string memory color, string memory description) internal pure returns (string memory) {
        string memory svg = string.concat('<svg xmlns="http://www.w3.org/2000/svg" width="640" height="640" viewBox="0 0 640 640"><rect width="640" height="640" fill="#13171a"/><g fill="none" stroke="',color,'" stroke-width="6"><path d="M40 160h120v120h70M40 480h120V360h70M410 280h70V160h120M410 360h70v120h120"/><rect x="210" y="210" width="220" height="220" rx="12"/><path d="M230 320q90-100 180 0-90 100-180 0Z"/><circle cx="320" cy="320" r="29"/></g><g fill="',color,'" font-family="monospace" text-anchor="middle"><text x="320" y="115" font-size="30">FILLOUT</text><text x="320" y="520" font-size="28">',label,'</text></g></svg>');
        return string.concat('data:application/json;base64,',Base64.encode(bytes(string.concat('{"name":"',name,'","description":"',description,'","image":"data:image/svg+xml;base64,',Base64.encode(bytes(svg)),'"}'))));
    }
    function part(uint256 id) internal pure returns (string memory) {
        require(id < 2, "unknown part");
        return uri(id == 0 ? "FillOut Quote" : "FillOut Settle", id == 0 ? "QUOTE" : "SETTLE", id == 0 ? "#d3b7a1" : "#a6c4c3", "Transferable FillOut component. Free and paid components are identical. Burn components after mint closure to assemble a Circuit.");
    }
    function circuit(uint256 id, uint8 tier) internal pure returns (string memory) {
        string memory name = tier == 0 ? "Common" : tier == 1 ? "Rare" : "Epic";
        return uri(string.concat("FillOut ",name," #",Strings.toString(id)),name,tier == 0 ? "#b7c1c7" : tier == 1 ? "#a6c4c3" : "#d3b7a1","FillOut Circuit assembled by permanently burning Quote and Settle components. Mining eligibility follows the fixed seven-day contract window.");
    }
}

FillOutParts.sol.content:
// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.27;
import "@openzeppelin/contracts/token/ERC1155/ERC1155.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/cryptography/EIP712.sol";
import "@openzeppelin/contracts/utils/cryptography/SignatureChecker.sol";
import "./AgentGate.sol";
import "./FillOutMetadata.sol";
interface IAssemblyReadiness { function rewardToken() external view returns (address); }

/// @notice Fungible Quote (0) and Settle (1). Free and paid parts are identical.
contract FillOutParts is ERC1155, ReentrancyGuard, EIP712 {
    AgentGate public immutable gate;
    address public immutable creator;
    address public immutable team;
    address payable public immutable liquidity;
    address public immutable priceSigner;
    address public assembler;
    uint256 public openedAt;
    uint256 public soldOutAt;
    uint256 public quoteIssued = 2300;
    uint256 public settleIssued = 575;
    uint256 public freeClaims;
    mapping(bytes32 => bool) public claimedAgent;
    mapping(address => bool) public claimedWallet;
    bytes32 public constant PRICE_TYPEHASH = keccak256("Price(address account,uint256 quote,uint256 settle,uint256 unitWei,uint256 nonce,uint256 deadline)");
    struct Permit { bytes32 agentId; uint256 nonce; uint256 deadline; bytes signature; }
    struct Price { uint256 unitWei; uint256 nonce; uint256 deadline; bytes signature; }
    event Started(uint256 openedAt, uint256 deadline);
    event AssemblerBound(address indexed assembler);
    event Purchased(address indexed buyer, uint256 quote, uint256 settle, uint256 value, uint256 liquidityAmount, uint256 platformAmount);
    event StarterClaimed(address indexed buyer, bytes32 indexed agentId);
    event SoldOut(uint256 timestamp);
    constructor(address gate_, address creator_, address team_, address payable liquidity_, address priceSigner_, string memory uri_)
        ERC1155(uri_) EIP712("FillOut ETH Price", "1") {
        require(gate_.code.length > 0 && creator_ != address(0) && team_ != address(0) && liquidity_ != address(0) && priceSigner_ != address(0), "invalid setup");
        gate = AgentGate(gate_); creator = creator_; team = team_; liquidity = liquidity_; priceSigner = priceSigner_;
        _mint(team_, 0, 2300, ""); _mint(team_, 1, 575, "");
    }
    function bindAssembler(address candidate) external {
        require(msg.sender == creator && assembler == address(0) && candidate.code.length > 0 && openedAt == 0, "bind denied");
        assembler = candidate; emit AssemblerBound(candidate);
    }
    function uri(uint256 id) public view override returns (string memory) {
        require(id < 2, "unknown part");
        string memory configured = super.uri(id);
        return bytes(configured).length == 0 ? FillOutMetadata.part(id) : configured;
    }
    function start(uint256 timestamp) external {
        require(msg.sender == creator && openedAt == 0 && assembler != address(0) && timestamp >= block.timestamp, "start denied");
        require(IAssemblyReadiness(assembler).rewardToken() != address(0), "mining not funded");
        openedAt = timestamp; emit Started(timestamp, timestamp + 7 days);
    }
    function closesAt() public view returns (uint256) {
        if (openedAt == 0) return 0;
        uint256 deadline = openedAt + 7 days;
        return soldOutAt != 0 && soldOutAt < deadline ? soldOutAt : deadline;
    }
    function closed() public view returns (bool) { return openedAt != 0 && block.timestamp >= closesAt(); }
    function _open() internal view { require(openedAt != 0 && block.timestamp >= openedAt && !closed(), "mint closed"); }
    function claimFree(Permit calldata p) external nonReentrant {
        _open(); require(freeClaims < 4998 && !claimedAgent[p.agentId] && !claimedWallet[msg.sender], "starter unavailable");
        gate.consume(msg.sender, p.agentId, keccak256("FREE"), p.nonce, p.deadline, p.signature);
        claimedAgent[p.agentId] = true; claimedWallet[msg.sender] = true; ++freeClaims;
        _issue(msg.sender, 4, 1); emit StarterClaimed(msg.sender, p.agentId);
    }
    /// @dev The price signer attests the ETH equivalent of USD 0.30 per part.
    /// Its honesty and price-feed freshness remain an explicit off-chain trust assumption.
    function buy(uint256 quote, uint256 settle, Permit calldata p, Price calldata price) external payable nonReentrant {
        _open(); require(quote + settle > 0 && quote <= 77700 && settle <= 19425, "invalid quantity");
        require(price.unitWei > 0 && price.deadline >= block.timestamp && price.deadline <= block.timestamp + 5 minutes, "price expiry");
        bytes32 digest = _hashTypedDataV4(keccak256(abi.encode(PRICE_TYPEHASH, msg.sender, quote, settle, price.unitWei, price.nonce, price.deadline)));
        require(SignatureChecker.isValidSignatureNow(priceSigner, digest, price.signature), "invalid price");
        require(msg.value == (quote + settle) * price.unitWei, "exact ETH required");
        gate.consume(msg.sender, p.agentId, keccak256(abi.encode("BUY", quote, settle, digest)), p.nonce, p.deadline, p.signature);
        _issue(msg.sender, quote, settle);
        uint256 lp = msg.value;
        (bool a,) = liquidity.call{value:lp}(""); require(a, "liquidity payout");
        emit Purchased(msg.sender, quote, settle, msg.value, lp, msg.value-lp);
    }
    function _issue(address to, uint256 quote, uint256 settle) internal {
        require(quoteIssued + quote <= 80000 && settleIssued + settle <= 20000, "supply cap");
        quoteIssued += quote; settleIssued += settle;
        if (quoteIssued == 80000 && settleIssued == 20000) { soldOutAt = block.timestamp; emit SoldOut(block.timestamp); }
        if (quote > 0) _mint(to, 0, quote, "");
        if (settle > 0) _mint(to, 1, settle, "");
    }
    function burnForCircuit(address from, uint256 quote, uint256 settle) external {
        require(msg.sender == assembler && closed() && isApprovedForAll(from, msg.sender), "burn denied");
        _burn(from, 0, quote); _burn(from, 1, settle);
    }
}

VRAM.sol.content:
// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.27;
import "@openzeppelin/contracts/token/ERC20/ERC20.sol";

interface IVramV2Factory { function getPair(address,address) external view returns (address); }
interface IVramV2Pair {
    function token0() external view returns (address);
    function token1() external view returns (address);
    function factory() external view returns (address);
}

/// @notice Fixed 2% VRAM fee on transfers to/from registered V2-compatible pools.
/// Normal wallet transfers and mining claims are not taxed.
contract VRAM is ERC20 {
    uint256 public constant TRADING_FEE_BPS = 200;
    address public immutable creator;
    address public immutable feeRecipient;
    address public dexFactory;
    mapping(address => bool) public tradingPools;
    event DexFactoryBound(address indexed factory);
    event PoolRegistered(address indexed pool, address indexed pairedToken);
    event TradingFee(address indexed from, address indexed to, uint256 gross, uint256 fee);

    constructor(address liquidity, address mining, address creator_, address team_) ERC20("FillOut VRAM", "VRAM") {
        require(liquidity != address(0) && mining.code.length > 0 && creator_ != address(0) && team_ != address(0), "invalid recipients");
        creator = creator_; feeRecipient = team_;
        _mint(liquidity, 200_000_000 ether); _mint(mining, 800_000_000 ether);
    }
    /// @dev One-time setup; choose a reviewed fee-on-transfer-compatible V2 DEX.
    function bindDexFactory(address factory_) external {
        require(msg.sender == creator && dexFactory == address(0) && factory_.code.length > 0, "factory bind denied");
        dexFactory = factory_; emit DexFactoryBound(factory_);
    }
    /// @notice Anyone may register an actual pair of the fixed DEX factory.
    /// An EOA or arbitrary wallet cannot be designated as a taxable pool.
    function registerPool(address pair) external {
        require(dexFactory != address(0) && pair.code.length > 0 && !tradingPools[pair], "invalid pool");
        address a = IVramV2Pair(pair).token0(); address b = IVramV2Pair(pair).token1();
        require(a != b && (a == address(this) || b == address(this)), "not VRAM pair");
        require(IVramV2Pair(pair).factory() == dexFactory && IVramV2Factory(dexFactory).getPair(a,b) == pair, "unrecognized pair");
        tradingPools[pair] = true; emit PoolRegistered(pair, a == address(this) ? b : a);
    }
    function _update(address from, address to, uint256 value) internal override {
        if (from != address(0) && to != address(0) && from != to && (tradingPools[from] || tradingPools[to])) {
            uint256 fee = value / 50;
            if (fee > 0) super._update(from, feeRecipient, fee);
            super._update(from, to, value - fee);
            emit TradingFee(from, to, value, fee);
        } else super._update(from, to, value);
    }
}

